import { readFile } from "node:fs/promises";
import { join } from "node:path";
import type { KnowledgeBase } from "@/types/questionnaire";
import { PADDED_KB_ID } from "@/lib/schemas";

// Padded knowledge bases for the scale test are generated by eval/distractors.py and read from disk on demand.
// They are local-evaluation only (up to ~500K characters each), so they are kept out of the deployed bundle.

const cache = new Map<string, KnowledgeBase>();

export async function loadPaddedKb(id: string): Promise<KnowledgeBase | null> {
  if (!PADDED_KB_ID.test(id)) return null;
  const hit = cache.get(id);
  if (hit) return hit;
  const dir = process.env.EVAL_KB_DIR || join(process.cwd(), "eval", "data", "kb");
  try {
    const kb = JSON.parse(await readFile(join(dir, `${id}.json`), "utf8")) as KnowledgeBase;
    cache.set(id, kb);
    return kb;
  } catch {
    return null;
  }
}
